import * as T from './vendor/three.js';
export function selectGroundTiles(tiles,camera,maxPixels=16*1024*1024,{slots=4,range=420}={}){const selected=[];let pixels=0;for(const tile of tiles.map(t=>({...t,d:Math.hypot((t.minX+t.maxX)/2-camera.x,(t.minZ+t.maxZ)/2-camera.z)})).filter(t=>t.d<range).sort((a,b)=>a.d-b.d)){const cost=tile.width*tile.height;if(selected.length===slots||pixels+cost>maxPixels)continue;selected.push(tile);pixels+=cost}return selected}
function createTier(tiles,{slots=4,range=420,maxPixels=16*1024*1024,fade=8,blank=false,detail=0}={}){
 const layers=Array.from({length:slots},()=>({texture:null,bounds:{minX:1e8,minZ:1e8,maxX:1e8+1,maxZ:1e8+1},fade,blank,detail,textureUniform:{value:null},extentUniform:{value:new T.Vector4(1e8,1e8,1,1)}})),loaded=new Map(),pending=new Set(),loader=new T.TextureLoader();let selected=[],next=0;
 function bind(){layers.forEach((layer,i)=>{const tile=selected[i],texture=tile&&loaded.get(tile.id);layer.textureUniform.value=texture||null;layer.extentUniform.value.set(texture?tile.minX:1e8,texture?tile.minZ:1e8,texture?tile.maxX-tile.minX:1,texture?tile.maxZ-tile.minZ:1)})}
 function pump(){for(const tile of selected){if(pending.size>=2)break;if(loaded.has(tile.id)||pending.has(tile.id))continue;pending.add(tile.id);loader.load('./'+tile.image,texture=>{pending.delete(tile.id);if(!selected.some(t=>t.id===tile.id)){texture.dispose();pump();return}texture.colorSpace=T.SRGBColorSpace;texture.magFilter=T.LinearFilter;texture.minFilter=T.LinearMipmapLinearFilter;texture.anisotropy=8;loaded.set(tile.id,texture);bind();pump()},undefined,()=>pending.delete(tile.id))}}
 return{layers,update(camera){const now=performance.now();if(now<next)return;next=now+250;selected=selectGroundTiles(tiles,camera,maxPixels,{slots,range});for(const[id,texture]of loaded)if(!selected.some(t=>t.id===id)){texture.dispose();loaded.delete(id)}bind();pump()},get stats(){return{loaded:loaded.size,inflight:pending.size,pixels:selected.reduce((sum,t)=>sum+(loaded.has(t.id)?t.width*t.height:0),0)}}};
}
// Native Wainuiomata tiles and 0.5m regional urban tiles share the fine slots; 2m valley tiles stream
// in a wider ring. Regional photographs mark sea/outside coverage as white, which falls back to procedural ground.
export function createGroundDetail(manifest,regional=null){
 const fine=createTier([...manifest.tiles,...(regional?.urban.tiles||[])],{blank:true}),valley=regional?createTier(regional.valley.tiles,{range:2600,maxPixels:4*1024*1024,fade:40,blank:true,detail:.2}):null;
 return{layers:fine.layers,valleyLayers:valley?.layers||[],update(camera){fine.update(camera);valley?.update(camera)},get stats(){const a=fine.stats,b=valley?.stats||{loaded:0,inflight:0,pixels:0};return{loaded:a.loaded+b.loaded,inflight:a.inflight+b.inflight,pixels:a.pixels+b.pixels,valley:b}}};
}
